def f03(s):
    L = s.split("\n")
    def rep(prefix, new):
        k = [i for i, l in enumerate(L) if l.startswith(prefix)]; assert k, prefix; L[k[0]] = new
    rep("| А6 |", "| А6 | Қорғаныс қабаты тордың екі бағыттағы стерженьдері **түйіскен жазықтықтан** бетон бетіне дейін: фундамент 50 (асты, үсті), плита 40 (асты, үсті), стена 40 (екі жағынан). Колонна, ригель — шаблон бойынша; Ø үлкейсе хомутқа қалатын бетон тексеріледі | есеп |")
    rep("| Б5 |", "| Б5 | Шеттегі П-скоба: иілген бөлігінің биіктігі сечениеден (қалыңдық − екі жақтағы қорғаныс), аяғының ұзындығы = таңдалған нахлёст ұзындығы | есеп |")
    rep("| Д5 |", "| Д5 | Шеттегі П-скоба негізгі арматурамен бірдей Ø; биіктігі сечениеден, аяғы = нахлёст | есеп |")
    rep("| Е5 |", "| Е5 | Шетінде П-скоба: биіктігі плита қалыңдығынан (− екі жақтағы қорғаныс), аяғы = нахлёст; парапет аналогтан | есеп |")
    rep("| Г1 |", "| Г1 | Тік арматура стенаның ішкі жағында, көлденең арматура/хомут оны сыртынан орайды. Тік Ø тек төмен қарай үлкейеді (жоғарыда Ø25 керек болса, астынан да Ø25) | wall_chk |")
    return "\n".join(L)
rw(os.path.join(OBS, "03_Армирование — қатаң чек-лист.md"), f03)
def f01(s):
    a = "| Қорғаныс қабаты кестесі: элемент × бет (осьтен бе, беттен бе) | | ереже / сұрақ |"; assert a in s
    return s.replace(a, "| Қорғаныс қабаты (тор стерженьдері түйіскен жазықтықтан бетке дейін): фундамент 50/50, плита 40/40, стена 40/40; колонна, ригель — шаблон бойынша | | пайдаланушы (12.11.2026) |")
